=== ITEM 1: rpc_data_column_sidecars_by_root.go ===
func (s *Service) dataColumnSidecarByRootRPCHandler(...):
- Validates request with validateDataColumnsByRootRequest (checks MaxRequestDataColumnSidecars)
- Retrieves from s.cfg.dataColumnStorage.Get(root, columns)  [VerifiedRODataColumn]
- Filters by minReqSlot: sidecars below minReqSlot are skipped
- Streams remaining validated sidecars

validateDataColumnsByRootRequest: only checks total count <= MaxRequestDataColumnSidecars, does NOT validate column index values or duplicate roots.

=== ITEM 2: engine_client.go ReconstructDataColumnSidecars ===
func (s *Service) ReconstructDataColumnSidecars(...):
  blobAndProofV2s, err := s.GetBlobsV2(ctx, versionedHashes)
  // Return early if len(blobAndProofV2s) == 0
  for _, blobsAndProofs := range blobAndProofV2s {
    if blobsAndProofs == nil { return nil, error }
    blobs = append(blobs, blobsAndProofs.Blob)
    cellProofs = append(cellProofs, blobsAndProofs.KzgProofs...)
  }
  dataColumnSidecars, err := peerdas.ConstructDataColumnSidecars(signedROBlock, blobs, cellProofs)
  // "We trust the execution layer we are connected to"
  verifiedRODataColumn := blocks.NewVerifiedRODataColumn(roDataColumn)
  // No cryptographic verification on EL-provided data

=== ITEM 3: broadcaster.go BroadcastDataColumnSidecar ===
func (s *Service) BroadcastDataColumnSidecar(root, dataColumnSubnet, dataColumnSidecar):
  // No custody/subscription check before broadcast
  go s.internalBroadcastDataColumnSidecar(ctx, root, dataColumnSubnet, dataColumnSidecar, forkDigest)

internalBroadcastDataColumnSidecar:
  // Uses findPeersIfNeeded - always tries to find peers for the subnet
  // Broadcasts regardless of whether node custodies this subnet
  // No check: "does this node custody column dataColumnSubnet?"

allDataColumnSubnets: returns all subnets when validators tracked (custody > 0)
  // This is called for peer subscription, not for broadcast gating

=== ITEM 4: data_columns_reconstruct.go broadcastMissingDataColumnSidecars ===
func (s *Service) broadcastMissingDataColumnSidecars(slot, proposerIndex, root, timeIntoSlot):
  missingColumns = [column for column in localNodeInfo.CustodyColumns if !s.hasSeenDataColumnIndex(slot, proposerIndex, column)]
  verifiedRODataColumnSidecars, _ = s.cfg.dataColumnStorage.Get(root, missingColumns)
  for _, verifiedRODataColumn := range verifiedRODataColumnSidecars {
    s.cfg.p2p.BroadcastDataColumnSidecar(root, subnet, verifiedRODataColumn.DataColumnSidecar)
    s.setSeenDataColumnIndex(slot, proposerIndex, verifiedRODataColumn.Index)
    // setSeenDataColumnIndex called AFTER BroadcastDataColumnSidecar
  }

// receiveDataColumnSidecar: calls setSeenDataColumnIndex BEFORE saving/processing
// reconstructSaveBroadcastDataColumnSidecars: saves toSaveSidecars (custody only), then schedules broadcast
// broadcastMissingDataColumnSidecars: sets seen ONLY for columns that were loaded+broadcast

=== ITEM 5: data_columns_reconstruct.go reconstructSaveBroadcastDataColumnSidecars ===
func (s *Service) reconstructSaveBroadcastDataColumnSidecars(ctx, slot, proposerIndex, root):
  verifiedSidecars, _ = s.cfg.dataColumnStorage.Get(root, nil)
  reconstructedSidecars, _ = peerdas.ReconstructDataColumnSidecars(verifiedSidecars)
  // Save only custody columns
  s.cfg.dataColumnStorage.Save(toSaveSidecars)
  // Note: "We do not call receiveDataColumn, because it will ignore incoming data columns
  //        via gossip while we did not broadcast (yet) the reconstructed data columns"
  s.scheduleMissingDataColumnSidecarsBroadcast(ctx, root, proposerIndex, slot)
  // broadcastMissingDataColumnSidecars eventually calls BroadcastDataColumnSidecar
  // BroadcastDataColumnSidecar does NOT re-run gossip validation
  // Reconstructed sidecars skip: ValidFields, CorrectSubnet, NotFromFutureSlot, SidecarParentSeen,
  //   SidecarParentValid, ValidProposerSignature, SidecarParentSlotLower, SidecarDescendsFromFinalized,
  //   SidecarInclusionProven, SidecarKzgProofVerified checks

